```rust
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Point {
    pub x: f32,
    pub y: f32,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Size {
    pub width: f32,
    pub height: f32,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Rect {
    pub x: f32,
    pub y: f32,
    pub width: f32,
    pub height: f32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LayoutError {
    InvalidInput,
}

pub fn tile_rect(texture: Size, depth: f32, camera: Point) -> Result<Rect, LayoutError> {
    let valid = texture.width.is_finite()
        && texture.height.is_finite()
        && camera.x.is_finite()
        && camera.y.is_finite()
        && depth.is_finite()
        && texture.width > 0.0
        && texture.height > 0.0
        && (0.0..=1.0).contains(&depth);
    if !valid {
        return Err(LayoutError::InvalidInput);
    }
    let raw_x = -camera.x * depth;
    let raw_y = -camera.y * depth;
    Ok(Rect {
        x: raw_x % texture.width - texture.width,
        y: raw_y % texture.height - texture.height,
        width: texture.width,
        height: texture.height,
    })
}
```

