#[path = "solution.rs"]
mod solution;

use solution::{tile_rect, LayoutError, Point, Rect, Size};

#[test]
fn positive_camera_coordinates_wrap_into_negative_tile() {
    let result = tile_rect(
        Size { width: 10.0, height: 8.0 },
        0.5,
        Point { x: 3.0, y: 5.0 },
    );
    assert_eq!(result, Ok(Rect { x: -1.5, y: -2.5, width: 10.0, height: 8.0 }));
}

#[test]
fn negative_camera_coordinates_use_euclidean_remainder() {
    let result = tile_rect(
        Size { width: 10.0, height: 8.0 },
        0.5,
        Point { x: -3.0, y: -5.0 },
    );
    assert_eq!(result, Ok(Rect { x: -8.5, y: -5.5, width: 10.0, height: 8.0 }));
}

#[test]
fn zero_and_exact_multiples_map_to_negative_dimension() {
    assert_eq!(
        tile_rect(
            Size { width: 10.0, height: 4.0 },
            1.0,
            Point { x: 20.0, y: -8.0 },
        ),
        Ok(Rect { x: -10.0, y: -4.0, width: 10.0, height: 4.0 })
    );
    assert_eq!(
        tile_rect(
            Size { width: 10.0, height: 4.0 },
            0.0,
            Point { x: 123.0, y: -456.0 },
        ),
        Ok(Rect { x: -10.0, y: -4.0, width: 10.0, height: 4.0 })
    );
}

#[test]
fn depth_endpoints_are_inclusive() {
    let texture = Size { width: 2.0, height: 3.0 };
    let camera = Point { x: 0.25, y: -0.5 };
    assert!(tile_rect(texture, 0.0, camera).is_ok());
    assert!(tile_rect(texture, 1.0, camera).is_ok());
}

#[test]
fn invalid_dimensions_and_depth_are_rejected() {
    let point = Point { x: 0.0, y: 0.0 };
    for (size, depth) in [
        (Size { width: 0.0, height: 1.0 }, 0.5),
        (Size { width: -1.0, height: 1.0 }, 0.5),
        (Size { width: 1.0, height: 0.0 }, 0.5),
        (Size { width: 1.0, height: -1.0 }, 0.5),
        (Size { width: 1.0, height: 1.0 }, -0.1),
        (Size { width: 1.0, height: 1.0 }, 1.1),
    ] {
        assert_eq!(tile_rect(size, depth, point), Err(LayoutError::InvalidInput));
    }
}

#[test]
fn every_non_finite_input_category_is_rejected() {
    let valid_size = Size { width: 1.0, height: 1.0 };
    let valid_point = Point { x: 0.0, y: 0.0 };
    assert_eq!(tile_rect(Size { width: f32::NAN, height: 1.0 }, 0.5, valid_point), Err(LayoutError::InvalidInput));
    assert_eq!(tile_rect(Size { width: 1.0, height: f32::INFINITY }, 0.5, valid_point), Err(LayoutError::InvalidInput));
    assert_eq!(tile_rect(valid_size, f32::NAN, valid_point), Err(LayoutError::InvalidInput));
    assert_eq!(tile_rect(valid_size, 0.5, Point { x: f32::NEG_INFINITY, y: 0.0 }), Err(LayoutError::InvalidInput));
    assert_eq!(tile_rect(valid_size, 0.5, Point { x: 0.0, y: f32::NAN }), Err(LayoutError::InvalidInput));
}

